SELECT ?film ?filmLabel ?director ?directorLabel ?death WHERE {
  VALUES ?film { dbr:Kanchana_Sita dbr:Ghost_of_the_China_Sea }
  # director property (dbo or dbp)
  ?film (dbo:director|dbp:director) ?director .
  OPTIONAL {
    { ?director dbo:deathDate ?death } UNION
    { ?director dbp:deathDate ?death } UNION
    { ?director dbp:death ?death } UNION
    { ?director dbp:death_date ?death } UNION
    { ?director dbp:date_of_death ?death }
  }
  OPTIONAL { ?film rdfs:label ?filmLabel . FILTER(langMatches(lang(?filmLabel), "EN")) }
  OPTIONAL { ?director rdfs:label ?directorLabel . FILTER(langMatches(lang(?directorLabel), "EN")) }
} ORDER BY ?film ?director ?death

